/**
 * Response contracts: what the server must send. The port checks every answer against these and
 * the harness shows any mismatch. Regenerate after a backend change (widgets:contract).
 */
import { s, type Infer } from '../../core/shape';

// <contract kyc.application.get>
/** GET /api/kyc/orgs/{id} → Dtos.KycApplicationView (KycController#get, kyc.application:read). Generated by widgets:contract. */
export const KYC_APPLICATION_GET = s.object('KycApplicationView', {
  id: s.nullable(s.string()),
  orgId: s.nullable(s.string()),
  orgType: s.nullable(s.string()),
  orgName: s.nullable(s.string()),
  parentOrgId: s.nullable(s.string()),
  treePath: s.nullable(s.array(s.object('OrgPathRow', {
    id: s.nullable(s.string()),
    type: s.nullable(s.string()),
    name: s.nullable(s.string()),
    depth: s.integer(),
  }))),
  depth: s.integer(),
  isSuspended: s.boolean(),
  status: s.nullable(s.string()),
  application: s.nullable(s.any()),
  submittedApplication: s.nullable(s.any()),
  submittedBy: s.nullable(s.string()),
  submittedAt: s.nullable(s.dateTime()),
  decidedBy: s.nullable(s.string()),
  decidedAt: s.nullable(s.dateTime()),
  decisionNote: s.nullable(s.string()),
  version: s.integer(),
  masked: s.boolean(),
  canEdit: s.boolean(),
  canSubmit: s.boolean(),
  canDecide: s.boolean(),
  createdAt: s.nullable(s.dateTime()),
  updatedAt: s.nullable(s.dateTime()),
});
export type KycApplicationGet = Infer<typeof KYC_APPLICATION_GET>;
// </contract kyc.application.get>

/*
 * The two endpoints below return Map<String, Object> on the server, so their contracts cannot be
 * generated; they are written from the frontend types the editor reads (kyc-schema-editor.ts
 * SchemaResponse, the list lookup). Keep them in step with KycController#schemaForOrg / #list.
 */
const LIST_ITEM = s.object('ListItem', {
  value: s.string(),
  label: s.nullable(s.string()),
});

const FIELD = s.object('SchemaField', {
  key: s.string(), label: s.string(), helpText: s.nullable(s.string()), dataType: s.string(),
  listCode: s.nullable(s.string()), listParentField: s.nullable(s.string()), required: s.string(),
  requiredWhen: s.nullable(s.any()), visibleWhen: s.nullable(s.any()), pattern: s.nullable(s.string()),
  minLength: s.nullable(s.integer()), maxLength: s.nullable(s.integer()),
  minValue: s.nullable(s.number()), maxValue: s.nullable(s.number()),
  derivedFrom: s.nullable(s.string()), canonicalTag: s.nullable(s.string()),
  sensitivity: s.string(), sensitive: s.boolean(),
});

/** GET /api/kyc/schema/{orgId} → the resolved master profile (KycController#schemaForOrg, kyc.form:read). */
export const KYC_SCHEMA_GET = s.object('SchemaResponse', {
  profile: s.object('Profile', { code: s.string(), country: s.string(), licenceType: s.string() }),
  schema: s.object('SchemaRef', { code: s.string(), version: s.integer() }),
  sections: s.array(s.object('SchemaSection', {
    key: s.string(), title: s.string(), kind: s.enum('OBJECT', 'LIST', 'DOCUMENTS'), step: s.nullable(s.integer()),
    minItems: s.nullable(s.integer()), maxItems: s.nullable(s.integer()), visible: s.boolean(),
    fields: s.array(FIELD),
  })),
  rules: s.array(s.any()),
  submitRules: s.array(s.any()),
  lists: s.map(s.array(LIST_ITEM)),
  params: s.nullable(s.map(s.any())),
});

/** GET /api/kyc/lists/{code}[?parent=] → { items } (KycController#list, kyc.form:read). */
export const KYC_LIST_GET = s.object('ListResponse', { items: s.array(LIST_ITEM) });

/*
 * What the editor SENDS. The server takes Map<String, Object> for save and submit (no record to
 * generate from), so these are written from what KycController reads (#save: the whole KYC
 * document as the body; #submit: { sendToChecker }). Withdraw reads no body; the editor sends {}.
 */
/** PUT /api/kyc/orgs/{id}?expectedVersion= - the KYC document: section key → section object or list of items. */
export const KYC_APPLICATION_SAVE_REQUEST = s.map(s.any());
/** POST /api/kyc/orgs/{id}/submit - optional: ask another ADMIN of the org to check it first. */
export const KYC_APPLICATION_SUBMIT_REQUEST = s.object('SubmitRequest', { sendToChecker: s.boolean() });
/** POST /api/kyc/orgs/{id}/withdraw - no body is read; an empty object is sent. */
export const KYC_APPLICATION_WITHDRAW_REQUEST = s.object('NoBody', {});
